import sys

class Resource:
    active_count = 0

    def __init__(self):
        Resource.active_count += 1
        print(f"Object Created. Active: {Resource.active_count}")

    def __del__(self):
        print(f"Object Destroyed. Active: {Resource.active_count - 1}")
        Resource.active_count -= 1

def main():
    n = int(sys.stdin.readline().strip())
    if n > 0:
        def create_resources():
            resources = []
            for i in range(n):
                r = Resource()
                resources.append(r)
            del resources

        create_resources()

if __name__ == "__main__":
    main()
